export class Public {
    /**
     * TZ §4.4 - the public filtered view, as a file. No watermark, no audit row
     * (there is no identity to record), and every cell screened by construction.
     *
     * Since ADR-016 this renders the **four closure sections** - overview, work
     * types, originality bands, faculties - from the released cube, and not the
     * seven of the internal export. Rechecks, escalation categories and usage are
     * distinct-entity counts with no decomposition over the cube, so a public
     * figure for them would necessarily include the checks of withheld cells,
     * which TZ §6.2 forbids «ни в каком виде, включая экспорт». Those four
     * sections are also exactly what the public dashboard shows, so the file is
     * now a faithful «выгрузка текущего представления» rather than a superset of
     * it. The internal export is unchanged.
     */
    public static publicExport<ThrowOnError extends boolean = false>(options: Options<PublicExportData, ThrowOnError>): RequestResult<PublicExportResponses, PublicExportErrors, ThrowOnError> {
        return (options.client ?? client).post<PublicExportResponses, PublicExportErrors, ThrowOnError>({
            url: '/api/public/export',
            ...options,
            headers: {
                'Content-Type': 'application/json',
                ...options.headers
            }
        });
    }
    
    /**
     * TZ §4.2 §4 - the faculty aggregate. The public contour never publishes
     * department grain; that is the internal contour's `/departments-matrix`.
     */
    public static faculties<ThrowOnError extends boolean = false>(options?: Options<FacultiesData, ThrowOnError>): RequestResult<FacultiesResponses, FacultiesErrors, ThrowOnError> {
        return (options?.client ?? client).get<FacultiesResponses, FacultiesErrors, ThrowOnError>({ url: '/api/public/faculties', ...options });
    }
    
    /**
     * TZ §4.2 §5 - the five originality bands and their shares.
     *
     * The bands are the distribution *inside* one released group, so they are
     * published with it: `Σ bands = total`, and a band is never the difference of
     * published numbers.
     */
    public static histogram<ThrowOnError extends boolean = false>(options?: Options<Histogram2Data, ThrowOnError>): RequestResult<Histogram2Responses, Histogram2Errors, ThrowOnError> {
        return (options?.client ?? client).get<Histogram2Responses, Histogram2Errors, ThrowOnError>({ url: '/api/public/histogram', ...options });
    }
    
    /**
     * TZ §4.5 - the published report snapshots.
     *
     * Snapshots are immutable artefacts that were screened when they were
     * generated, so there is nothing left to suppress; the witness is empty and
     * the guard only checks that no metric-shaped number slipped in. No
     * filesystem path is exposed.
     */
    public static reports<ThrowOnError extends boolean = false>(options?: Options<ReportsData, ThrowOnError>): RequestResult<ReportsResponses, unknown, ThrowOnError> {
        return (options?.client ?? client).get<ReportsResponses, unknown, ThrowOnError>({ url: '/api/public/reports', ...options });
    }
    
    /**
     * TZ §4.5 - bytes of a published report snapshot.
     *
     * An unpublished snapshot answers `404`, not `403`: the public contour must
     * not confirm that a draft exists.
     */
    public static download<ThrowOnError extends boolean = false>(options: Options<DownloadData, ThrowOnError>): RequestResult<DownloadResponses, DownloadErrors, ThrowOnError> {
        return (options.client ?? client).get<DownloadResponses, DownloadErrors, ThrowOnError>({ url: '/api/public/reports/{id}/download', ...options });
    }
    
    /**
     * Wiring probe kept from the scaffold until the frontend client is generated
     * in slice W2.2. Carries no data.
     */
    public static status<ThrowOnError extends boolean = false>(options?: Options<StatusData, ThrowOnError>): RequestResult<StatusResponses, unknown, ThrowOnError> {
        return (options?.client ?? client).get<StatusResponses, unknown, ThrowOnError>({ url: '/api/public/status', ...options });
    }
    
    /**
     * TZ §4.2 §1 - KPI cards for the selected period, with the same figures one
     * year earlier and the deltas between them.
     *
     * The comparison window is the same calendar months a year earlier, at their
     * true lengths (`domain::Period::shift_years`), so a 28-day February is
     * compared against a 29-day one rather than being silently truncated.
     */
    public static summary<ThrowOnError extends boolean = false>(options?: Options<Summary2Data, ThrowOnError>): RequestResult<Summary2Responses, Summary2Errors, ThrowOnError> {
        return (options?.client ?? client).get<Summary2Responses, Summary2Errors, ThrowOnError>({ url: '/api/public/summary', ...options });
    }
    
    /**
     * TZ §4.2 §2 - checks and mean originality by month.
     *
     * Months with no data at all are absent; months whose every cell was withheld
     * are present with both metrics as `"insufficient_data"`, so the chart draws
     * the gap explicitly (TZ §8 «состояние "недостаточно данных" отображается
     * явно»).
     */
    public static timeseries<ThrowOnError extends boolean = false>(options?: Options<Timeseries2Data, ThrowOnError>): RequestResult<Timeseries2Responses, Timeseries2Errors, ThrowOnError> {
        return (options?.client ?? client).get<Timeseries2Responses, Timeseries2Errors, ThrowOnError>({ url: '/api/public/timeseries', ...options });
    }
    
    /**
     * TZ §4.2 §3 - checks and mean originality per work type.
     */
    public static workTypes<ThrowOnError extends boolean = false>(options?: Options<WorkTypes2Data, ThrowOnError>): RequestResult<WorkTypes2Responses, WorkTypes2Errors, ThrowOnError> {
        return (options?.client ?? client).get<WorkTypes2Responses, WorkTypes2Errors, ThrowOnError>({ url: '/api/public/work-types', ...options });
    }
    
    /**
     * TZ §4.2 §9 - the period split by academic year.
     */
    public static yoy<ThrowOnError extends boolean = false>(options?: Options<Yoy2Data, ThrowOnError>): RequestResult<Yoy2Responses, Yoy2Errors, ThrowOnError> {
        return (options?.client ?? client).get<Yoy2Responses, Yoy2Errors, ThrowOnError>({ url: '/api/public/yoy', ...options });
    }
}

export class Ops {
    /**
     * Liveness: the process is up.
     */
    public static healthz<ThrowOnError extends boolean = false>(options?: Options<HealthzData, ThrowOnError>): RequestResult<HealthzResponses, unknown, ThrowOnError> {
        return (options?.client ?? client).get<HealthzResponses, unknown, ThrowOnError>({ url: '/healthz', ...options });
    }
    
    /**
     * Readiness: the database answers **and** the warehouse is fresh.
     *
     * TZ §3.3.3 requires an internal refresh at least once a day, so a warehouse
     * whose newest succeeded ingest batch is older than
     * `APP_INGEST_MAX_AGE_SECONDS` (26 h by default - the nightly 02:00 tick plus
     * two hours of slack) is **degraded**: it still serves, but it is not ready to
     * take traffic in a rotation.
     *
     * A warehouse with **no succeeded batch at all** is ready. That is a fresh
     * install or a fixture database; reporting it as stale would keep a brand-new
     * deployment permanently out of its own load balancer, and "never imported" is
     * a condition the ingest metrics show plainly (`ingest_batches_total 0`).
     */
    public static readyz<ThrowOnError extends boolean = false>(options?: Options<ReadyzData, ThrowOnError>): RequestResult<ReadyzResponses, ReadyzErrors, ThrowOnError> {
        return (options?.client ?? client).get<ReadyzResponses, ReadyzErrors, ThrowOnError>({ url: '/readyz', ...options });
    }
}
